import{_ as o,o as a,c as t,a0 as d}from"./chunks/framework.BGyYNsHo.js";const m=JSON.parse('{"title":"Tránsito 1D por volúmenes finitos explícitos (FLOW_ROUTING FV)","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/modificaciones-motor/06-transito-por-volumenes-finitos.md","filePath":"es/explanation/modificaciones-motor/06-transito-por-volumenes-finitos.md"}'),n={name:"es/explanation/modificaciones-motor/06-transito-por-volumenes-finitos.md"};function s(i,e,r,l,c,p){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="transito-1d-por-volumenes-finitos-explicitos-flow-routing-fv" tabindex="-1">Tránsito 1D por volúmenes finitos explícitos (<code>FLOW_ROUTING FV</code>) <a class="header-anchor" href="#transito-1d-por-volumenes-finitos-explicitos-flow-routing-fv" aria-label="Permalink to &quot;Tránsito 1D por volúmenes finitos explícitos (`FLOW_ROUTING FV`)&quot;">​</a></h1><h2 id="motivacion" tabindex="-1">Motivación <a class="header-anchor" href="#motivacion" aria-label="Permalink to &quot;Motivación&quot;">​</a></h2><p>El SWMM oficial solo ofrece esquemas implícitos con linealización (onda dinámica) u ondas cinemática/permanente. El solver de onda dinámica, aunque es el estándar de la industria, tiene dificultades bien documentadas con el flujo transcrítico, la propagación de frentes bruscos y la transición seco/húmedo. La extensión <code>FLOW_ROUTING FV</code> agrega un solver 1D de <em>volúmenes finitos explícito y conservativo</em> de tipo Godunov, que resuelve el flujo transcrítico de forma nativa y maneja seco/húmedo sin las ramas ad hoc de la onda dinámica.</p><h2 id="arquitectura-del-solver" tabindex="-1">Arquitectura del solver <a class="header-anchor" href="#arquitectura-del-solver" aria-label="Permalink to &quot;Arquitectura del solver&quot;">​</a></h2><p>El solver vive en <code>src/engine/hydraulics/fv/</code>. Cada conducto se discretiza en celdas (por defecto al menos <code>FV_MIN_CELLS</code> = 4 por conducto, o con un blanco de longitud <code>FV_CELL_LENGTH</code>); el estado conservado de cada celda es el área hidráulica $A$ y el caudal $Q$. El paso temporal global obedece la condición de Courant, y el solver sub-pasea internamente a su propio límite CFL, de modo que el paso de tránsito (de reporting/forzamiento) no necesita encogerse por estabilidad.</p><p>Las opciones principales (claves <code>FV_*</code> en <code>[OPTIONS]</code>) son:</p><table tabindex="0"><thead><tr><th>Opción</th><th>Defecto</th><th>Descripción</th></tr></thead><tbody><tr><td><code>FV_CFL</code></td><td>0.5</td><td>número de Courant</td></tr><tr><td><code>FV_RIEMANN</code></td><td>HLLC</td><td>solver de Riemann (HLL / HLLC)</td></tr><tr><td><code>FV_ORDER</code></td><td>1</td><td>orden espacial (1 = Godunov, 2 = MUSCL–Hancock)</td></tr><tr><td><code>FV_LIMITER</code></td><td>MINMOD</td><td>limitador de pendiente (MINMOD/VANLEER/SUPERBEE)</td></tr><tr><td><code>FV_CELL_LENGTH</code></td><td>0</td><td>blanco de $\\Delta x$ (0 = solo piso de celdas)</td></tr><tr><td><code>FV_MIN_CELLS</code></td><td>4</td><td>piso de celdas por conducto</td></tr><tr><td><code>FV_SLOT_CELERITY</code></td><td>100 ft/s</td><td>celeridad de presión (ancho de ranura)</td></tr><tr><td><code>FV_NODE_COUPLING</code></td><td>SEMI_IMPLICIT</td><td>acoplamiento nodo–celda</td></tr><tr><td><code>FV_STRUCTURE_COUPLING</code></td><td>SUBSTEP</td><td>cuándo se re-evalúan las estructuras</td></tr><tr><td><code>FV_LTS</code></td><td>true</td><td>paso de tiempo local</td></tr><tr><td><code>FV_LTS_MAX_TIERS</code></td><td>6</td><td>máximo de niveles LTS</td></tr><tr><td><code>FV_DISPERSION</code></td><td>0</td><td>coeficiente de dispersión longitudinal</td></tr></tbody></table><p><em>Tabla: Opciones del solver 1D de volúmenes finitos.</em></p><h2 id="disenos-clave" tabindex="-1">Diseños clave <a class="header-anchor" href="#disenos-clave" aria-label="Permalink to &quot;Diseños clave&quot;">​</a></h2><ul><li><strong>Nodos algebraicos</strong>: las cámaras de unión no son estados con área (como en la onda dinámica, donde el área de trabajo pertenece a los conductos); un nodo de grado 2 sin aporte lateral pasa los flujos directamente como una cara, y los demás nodos resuelven su carga desde el balance instantáneo de flujos por subpaso. Esto elimina el límite de paso de milisegundos que un área de cámara imponía al modelo completo.</li><li><strong>Acoplamiento nodo–celda semi-implícito</strong>: el flujo de cada cara de acoplamiento se linealiza en la carga del nodo, lo que saca al nodo del límite de estabilidad explícito (la cámara, no la tubería, era el factor limitante del subpaso). La conservación no se altera: el flujo corregido es el que ven tanto el nodo como la celda. Con <code>FV_NODE_PICARD_SWEEPS</code> &gt; 1 se re-evalúan área, ancho y flujos de Riemann en cada barrido.</li><li><strong>Paso de tiempo local (LTS)</strong>: las celdas rígidas (conductos cortos, presurizados) avanzan a su propio $\\Delta t = 2^k,\\Delta t_0$ mientras el resto avanza al paso global; cuando el reparto no separa nada, el solver cae al camino de paso global bit a bit.</li><li><strong>Estructuras</strong>: las ecuaciones de bombas/orificios/vertederos/ descargas se re-evalúan por defecto en <em>cada</em> subpaso explícito (<code>FV_STRUCTURE_COUPLING SUBSTEP</code>), lo que es físicamente exacto; la alternativa es una vez por paso de tránsito.</li><li><strong>Backends</strong>: el mismo núcleo escalar se compila para CPU, OpenMP y dispositivos (CUDA/HIP/SYCL mediante plugins Kokkos); el resultado debe ser bit a bit idéntico entre backends.</li></ul>',10)])])}const v=o(n,[["render",s]]);export{m as __pageData,v as default};
